                idx = nxt
                k -= bit[nxt]
            mask >>= 1
        return idx + 1

    ans = [0] * N

    for i in range(N, 0, -1):
        pos = kth(P[i - 1])
        ans[pos - 1] = i
        add(pos, -1)

